type ProviderQuote = {
  providerId: string;
  priceMarketCode: string;
  productCode: string;
  buy: number | null;
  sell: number | null;
  unit:
    | "vnd_per_chi"
    | "vnd_per_luong"
    | "thousand_vnd_per_chi"
    | "thousand_vnd_per_luong";
  quotedAt: string;
  sourceUrl: string;
};

type PriceTick = {
  provider_id: string;
  market_code: string;
  gold_type: string;
  buy_price_per_luong_vnd: number;
  sell_price_per_luong_vnd: number;
  quoted_at: string;
  source_url: string;
};
